window.DOSIK=window.DOSIK||{};DOSIK["mg_diag"]={"1":[{"t":"tree","title":"경영진단의 전제","root":"경영진단의 의의와 절차","branches":[["경영이념","기업의 명확한 경영이념 정립을 위한 가치체계를 구축해야 한다"],["기업가 정신","새로운 사업기회창출을 위한 기업가 정신을 갖고 있어야 한다"],["신뢰","이해관계자의 신뢰를 받고 있어야 한다"]]},{"t":"tree","title":"경영진단의 태도","root":"경영진단","branches":[["강점과 약점","경영자는 경쟁기업과 대비한 경영상의 강점과 약점을 상세히 파악해야 한다"],["문제점","문제점을 명확하게 파악하고, 그 해결에 초점을 맞추어야 한다"],["균형","여러 조직, 기능, 활동의 균형을 중요시해야 한다"],["계속기업","계속기업 가정 하에 계속실체로서 진단되어야 한다"],["전체","전체를 대상으로 진단하는 태도가 필요하다"]]},{"t":"table","title":"이해관계자별 목적","head":["이해관계자","목적"],"rows":[["주주","투자정보를 획득하여 투자여부를 판단하기 위함이다"],["금융기관","자금차입자의 원리금 지급능력을 파악하기 위함이다"],["경영자","경영계획수립 및 경영 의사결정을 위한 기초자료를 획득하기 위함이다"],["고객","제품의 품질과 사후서비스의 가능성을 평가하기 위함이다"]]}],"2":[{"t":"def","term":"경영분석","text":"기업의 내부 및 외부 이해관계자의 경제적 의사결정에 필요한 정보 산출 · 회계자료 및 비회계자료를 폭넓게 이용한다"},{"t":"tree","title":"경영분석 방법","root":"경영분석의 방법론","branches":[["지수법","여러 재무비율을 동시에 고려해 재무상태와 경영성과 평가 · 가중치를 부여해 지수를 산출하는 가중비율종합법이라고도 한다 · 월(Wall), 트랜트(Trant), 브리체트(Brichett)"],["질적 요인","경영자의 자질, 기업 역사, 사업 전망 같은 질적 요인도 고려"],["비율분석","산출된 재무비율을 표준비율과 비교하는 방법이다"],["실수분석","재무제표상에 표시된 각 항목의 실제 값을 사용하여 분석하는 방법이다"],["산업분석","산업의 특성이나 동향을 파악하는 데 이용하는 방법이다"],["경제분석","전체 경제활동의 동향이나 방향을 파악하는 데 이용하는 방법이다"]]},{"t":"tree","title":"분석자료","root":"경영분석 자료","branches":[["비회계자료","경제관련자료와 경제분석 통계자료가 포함된다"],["질적자료","경영자의 능력, 제품의 질 등 주관적 속성을 지닌 자료이다"],["양적자료","손익계산서, 재무상태표 등 계량적 속성을 지닌 자료이다"]]}],"3":[{"t":"def","term":"현금흐름표","text":"기업의 재무정보를 제공하는 주요 재무제표의 하나이다","ex":["사용 방식 · 다른 재무제표와 같이 사용되는 경우","제공 정보 · 순자산의 변화, 재무구조","제공 정보 · 변화하는 상황과 기회에 적응하기 위하여 현금흐름의 금액과 시기를 조절하는 능력","제공 정보 · 능력을 평가하는 데 유용한 정보를 제공한다"]},{"t":"tree","title":"현금흐름의 활동 구분","root":"기업의 경영활동","branches":[["영업활동"],["투자활동"],["재무활동","장ㆍ단기 차입금을 상환하는 활동은 재무활동으로 분류된다"]]}],"4":[{"t":"table","title":"재무비율","head":["비율","설명"],"rows":[["부채비율","기업의 안정성을 측정하는 대표적인 재무비율이다"],["활동성비율","기업이 소유하고 있는 자산 등이 얼마나 효율적으로 이용되고 있는가를 평가하는데 이용되는 재무비율이다"],["레버리지비율","기업이 타인자본에 의존하고 있는 정도를 나타내는 재무비율이다"],["매출액영업이익률과 매출액순이익률","수익성을 측정하는데 이용되는 재무비율이다"]]},{"t":"tree","title":"자금운용의 안정성","root":"두 비율 모두 자금운용의 안정성 정도를 파악하기 위해 사용된다","branches":[["고정비율","비유동자산을 자기자본으로 나눈 비율이다 · 100 % 이하이면 재무적 안정성이 높다고 볼 수 있다"],["고정장기적합률","비유동자산 투자에 장기자본이 얼마만큼 사용되고 있는지를 나타낸다"]]},{"t":"tree","title":"유동성 비율","root":"유동성","branches":[["단기채무 상환 능력","평가하는 비율이다 · 기업에 자금을 대출한 금융기관이나 단기신용 제공자들이 많은 관심을 갖는 비율이다"],["현금비율","가장 보수적으로 유동성을 판단하는 비율이다"],["당좌비율","유동비율보다 유동성이 높다"]]}],"8":[{"t":"tree","title":"손익분기점 분석","root":"손익분기점(CVP)","branches":[["관계","판매량의 변화에 따른 매출액, 영업비용과 영업이익의 관계를 파악할 수 있다"],["변동비","조업도가 증가함에 따라 증가한다"],["공헌이익","매출액에서 그 매출을 실현하는데 소요된 변동비를 차감한 금액이다"],["손익분기점","영업이익이 0이 되는 매출수준을 의미한다"]]},{"t":"table","title":"영업레버리지와 재무레버리지","head":["구분","뜻","크기"],"rows":[["영업레버리지","기업이 영업비용 중에서 고정비를 부담하는 정도를 의미한다","영업레버리지도는 고정영업비용의 규모가 클수록 커진다"],["재무레버리지","기업이 자본조달의 결과로 이자비용을 부담하는 정도를 의미한다","재무레버리지도가 높은 기업일수록 주주들은 높은 기대수익률을 요구한다"]]},{"t":"table","title":"레버리지 효과","head":["조건","결과"],"rows":[["고정영업비 비중이 커질수록","매출액의 변화율보다 영업이익의 변화율이 더 높게 나타난다"],["판매량의 변화율이 일정할 때, 고정재무비 비중이 커질수록","영업이익의 변화율보다 주당순이익의 변화율이 더 높게 나타난다"],["결합레버리지 효과","매출액의 변화율보다 주당순이익의 변화율이 더 높게 나타난다"],["경기 하강기에 비유동자산 투자에 따른 레버리지의 상승","영업손실폭을 확대시킨다"]]}],"9":[{"t":"table","title":"시장가치비율","head":["비율","내용"],"rows":[["주가수익비율(PER)","일반적으로 성장성이 높거나 위험이 낮을수록 높다"],["주가장부가치비율(PBR)","기업의 미래 수익전망이 밝으면 높다"],["배당수익률","주당배당금을 주가로 나눈 비율이다"],["배당률","주당배당금이 같더라도 주식의 액면가가 다르면 배당률은 다르다"]]},{"t":"table","title":"자본비용","head":["구분","내용"],"rows":[["배당성장모형","배당금이 일정한 비율로 꾸준히 증가하는 것을 가정한다"],["증권시장선(SML) 접근법","위험을 반영하며, 배당금을 지급하지 않는 기업에도 적용 가능하다"],["우선주의 비용","우선주에 대한 배당수익률과 같다"],["가중평균자본비용(WACC)","자기자본비용과 세후 부채비용을 각각의 자본구조 비중으로 가중평균하여 구한다"]]},{"t":"tree","title":"현금흐름","root":"기업가치평가","branches":[["계산","현금흐름은 현금유입액에서 현금유출액을 차감하여 구한다"],["기준","이자비용과 배당을 차감하지 않은 상태의 영업이익을 기준으로 한다"],["감가상각비","현금흐름을 구할 때 가산해 주어야 한다"],["할인율","가중평균자본비용을 사용한다"]]}],"10":[{"t":"vs","title":"종합적 재무분석 기법","cols":[{"name":"장점","items":["여러 재무변수를 동시에 고려하는 종합적인 재무분석 기법이다","동일한 기준으로 여러 기업을 동시에 평가하므로 평가의 일관성을 유지할 수 있다"]},{"name":"한계","items":["사후적인 예측방법이므로 경영환경이 급변하는 경우 예측력이 떨어진다","판별함수를 추정하는 데 사용되는 재무비율의 선정에 있어서 이론적인 근거가 부족하다"]}]},{"t":"table","title":"기업부실 예측 기법","head":["기법","내용"],"rows":[["다중판별분석(multiple discriminant analysis)","여러 재무지표를 집단으로 분류하는 방법을 통하여 기업부실을 예측하는 기법이다"],["이원분류법(dichotomous classification technique)","기업의 부실 여부를 예측하고자 할 때 예측오류를 최소화할 수 있는 절삭점(cut-off point)을 정하고, 그 기준에 따라 부실화 가능성을 예측하는 기법이다"],["프로파일분석(profile analysis)","기업의 부실을 예측하기 위하여 부실기업과 건전기업 표본의 평균 재무비율이 각각 어떻게 변하는지를 관찰하는 기법이다"]]},{"t":"tree","title":"기업부실과 신용등급","root":"신용분석","branches":[["기술적 지급불능(technical insolvency)","일시적인 유동성 부족으로 인하여 만기가 된 채권을 상환하지 못하는 상태를 말한다"],["장기신용등급 BB+","투기적 등급이다"],["법정관리","지급불능상태에 있는 기업을 법원의 감독아래 채권자와 주주들의 이해관계를 조정하여 기업을 회생시키는 제도이다"],["회사채 평가등급","AAA ∼ D까지 10개의 등급으로 구분된다"]]}],"11":[{"t":"table","title":"산업구조분석","head":["요인","내용"],"rows":[["기업간 경쟁","제품차별화 정도가 적으면 기업간 경쟁강도가 높다 · 산업 내 경쟁은 경쟁업체가 많을수록, 규모가 비슷할수록 치열해진다"],["구매자의 교섭력","구매자가 대량의 제품을 매입할수록 커진다"],["공급자의 교섭력","공급하는 제품의 대체재가 없을수록 커진다"],["대체재","출현은 기존 기업의 가격 인상을 제한하는 효과가 있다"]]},{"t":"table","title":"경영환경 변수","head":["변화","영향"],"rows":[["급격한 환율상승","수입기업의 수익성을 악화시킨다"],["실질이자율의 상승","기업수지를 악화시켜 주가의 하락 요인으로 작용한다"],["통화량의 증가","기업 설비투자의 확대와 주식 매입수요를 증대시켜 주가의 상승 요인으로 작용한다"],["국제 원자재 가격의 상승","국내 수출기업의 채산성을 악화시킨다"]]}],"13":[{"t":"flow","title":"제품수명주기","steps":["도입기 · 매출은 상대적으로 저조하고 제조원가는 높다 · 비용이 많이 소요되어 수익성이 낮고 위험이 크다","성장기 · 높은 매출성장률과 시장점유율의 확대 · 이익이 크게 증가한다","성숙기 · 경쟁업체가 다수 등장해 기업 간 경쟁이 치열해진다 · 시장수요가 포화상태에 달해 매출성장률이 점진적으로 둔화한다","쇠퇴기"]},{"t":"tree","title":"제품포트폴리오관리","root":"제품포트폴리오관리","branches":[["분석 대상","기업의 현금흐름과 자원배분을 분석한다"],["축","수평축에 시장점유율, 수직축에 시장성장율을 나타낸다"],["현금젖소 제품","cash cows · 성장률이 낮으나 많은 현금흐름을 제공한다"],["개 제품","dogs · 수익성이 낮고 현금흐름이 적기 때문에 철수하는 것이 바람직하다"]]}],"14":[{"t":"tree","title":"경영전략 진단","root":"균형성과표(BSC)","branches":[["고객","고객의 수요를 늘리기 위하여 제품의 사용가치를 높여야 한다"],["외부환경 변화","외부환경 변화에 대처하기 위하여 지속적으로 변신해야 한다"],["생산성","투입자원 양에 비해 생산제품 양을 늘려 기업의 생산성을 향상시켜야 한다"],["가격경쟁력","제조원가를 낮추어 제품의 가격경쟁력을 키워야 한다"]]}]};
